diff --git a/src/ContactMgt.Codeunit.al b/src/ContactMgt.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/ContactMgt.Codeunit.al
@@ -0,0 +1,43 @@
+codeunit 50110 "Contact Management"
+{
+    Access = Internal;
+
+    procedure ContactToVendBusinessRelationExist(ContactNo: Code[20]): Boolean
+    var
+        ContactBusinessRelation: Record "Contact Business Relation";
+    begin
+        if ContactNo = '' then
+            exit(false);
+
+        ContactBusinessRelation.SetRange("Contact No.", ContactNo);
+        ContactBusinessRelation.SetRange("Link to Table", ContactBusinessRelation."Link to Table"::Vendor);
+
+        exit(ContactBusinessRelation.FindFirst());
+    end;
+
+    procedure GetVendorBusinessRelations(ContactNo: Code[20]; var TempContactBusinessRelation: Record "Contact Business Relation" temporary)
+    var
+        ContactBusinessRelation: Record "Contact Business Relation";
+    begin
+        TempContactBusinessRelation.DeleteAll();
+
+        ContactBusinessRelation.SetRange("Contact No.", ContactNo);
+        ContactBusinessRelation.SetRange("Link to Table", ContactBusinessRelation."Link to Table"::Vendor);
+
+        if ContactBusinessRelation.FindSet() then
+            repeat
+                TempContactBusinessRelation := ContactBusinessRelation;
+                TempContactBusinessRelation.Insert();
+            until ContactBusinessRelation.Next() = 0;
+    end;
+
+    procedure ValidateContactCompany(ContactNo: Code[20]): Boolean
+    var
+        Contact: Record Contact;
+    begin
+        Contact.SetLoadFields(Type);
+        if Contact.Get(ContactNo) then
+            exit(Contact.Type = Contact.Type::Company);
+        exit(false);
+    end;
+}
diff --git a/src/InstallAppCZL.Codeunit.al b/src/InstallAppCZL.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/InstallAppCZL.Codeunit.al
@@ -0,0 +1,44 @@
+codeunit 50111 "Install Application CZL"
+{
+    Access = Internal;
+
+    procedure MigrateVATEntries()
+    var
+        VATEntry: Record "VAT Entry";
+        ProcessedCount: Integer;
+    begin
+        VATEntry.SetRange("VAT Bus. Posting Group", 'DOMESTIC');
+        VATEntry.SetRange("Country/Region Code", 'CZ');
+        VATEntry.SetFilter("Registration No.", '<>%1', '');
+
+        if VATEntry.IsEmpty() then
+            exit;
+
+        VATEntry.SetLoadFields("Registration No.", "VAT Registration No.", "EU 3-Party Trade", "Registration No. CZL", "VAT Registration No. CZL", "EU 3-Party Trade CZL");
+        if VATEntry.FindSet() then
+            repeat
+                VATEntry."Registration No. CZL" := VATEntry."Registration No.";
+                VATEntry."VAT Registration No. CZL" := VATEntry."VAT Registration No.";
+                VATEntry."EU 3-Party Trade CZL" := VATEntry."EU 3-Party Trade";
+                VATEntry.Modify(false);
+
+                ProcessedCount += 1;
+
+                if ProcessedCount mod 1000 = 0 then
+                    LogMigrationProgress(ProcessedCount);
+
+            until VATEntry.Next() = 0;
+
+        LogMigrationComplete(ProcessedCount);
+    end;
+
+    local procedure LogMigrationProgress(ProcessedCount: Integer)
+    begin
+        // Log progress for user feedback
+    end;
+
+    local procedure LogMigrationComplete(TotalProcessed: Integer)
+    begin
+        // Log completion statistics
+    end;
+}
diff --git a/src/ReservationMgt.Codeunit.al b/src/ReservationMgt.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/ReservationMgt.Codeunit.al
@@ -0,0 +1,48 @@
+codeunit 50112 "Reservation Priority Mgt."
+{
+    Access = Internal;
+
+    procedure AllocateReservations()
+    var
+        ReservWorksheetLine: Record "Reservation Worksheet Line";
+        ProcessedCount: Integer;
+        TotalToProcess: Integer;
+    begin
+        ReservWorksheetLine.SetRange(Status, ReservWorksheetLine.Status::Open);
+        ReservWorksheetLine.SetRange("Priority Level", 1, 3);
+
+        if ReservWorksheetLine.IsEmpty() then
+            exit;
+
+        TotalToProcess := ReservWorksheetLine.Count();
+
+        if ReservWorksheetLine.FindSet(true) then begin
+            if not Confirm(AllocateReservationsQst, false, TotalToProcess) then
+                exit;
+
+            repeat
+                ReservWorksheetLine.Status := ReservWorksheetLine.Status::Allocated;
+                ReservWorksheetLine."Allocated Date" := Today();
+                ReservWorksheetLine."Allocated By" := UserId();
+                ReservWorksheetLine.Modify();
+
+                ProcessedCount += 1;
+
+                if ProcessedCount mod 50 = 0 then
+                    UpdateProgressDialog(ProcessedCount, TotalToProcess);
+
+            until ReservWorksheetLine.Next() = 0;
+        end;
+
+        Message(AllocatedMsg, ProcessedCount);
+    end;
+
+    local procedure UpdateProgressDialog(Processed: Integer; Total: Integer)
+    begin
+        // Update progress indicator
+    end;
+
+    var
+        AllocateReservationsQst: Label 'Allocate all open reservations (%1 records)?', Comment = '%1 = number of records';
+        AllocatedMsg: Label 'Successfully allocated %1 reservations.', Comment = '%1 = number of reservations';
+}

diff --git a/src/AgentStatus.Table.al b/src/AgentStatus.Table.al
new file mode 100644
--- /dev/null
+++ b/src/AgentStatus.Table.al
@@ -0,0 +1,85 @@
+table 50130 "EA Agent Status"
+{
+    Caption = 'Agent Run Status';
+    DataClassification = SystemMetadata;
+
+    fields
+    {
+        field(1; "Primary Key"; Code[10])
+        {
+            Caption = 'Primary Key';
+        }
+        field(2; "Last Run"; DateTime)
+        {
+            Caption = 'Last Run';
+        }
+        field(3; "Notifications Enabled"; Boolean)
+        {
+            Caption = 'Notifications Enabled';
+        }
+        field(4; Status; Enum "Agent Run State")
+        {
+            Caption = 'Status';
+        }
+        field(5; "Last Error Message"; Text[250])
+        {
+            Caption = 'Last Error Message';
+            DataClassification = CustomerContent;
+        }
+        field(6; "Retry Count"; Integer)
+        {
+            Caption = 'Retry Count';
+        }
+        field(7; "Next Retry Time"; DateTime)
+        {
+            Caption = 'Next Retry Time';
+        }
+    }
+
+    keys
+    {
+        key(PK; "Primary Key") { Clustered = true; }
+    }
+
+    procedure GetOrCreate(): Record "EA Agent Status"
+    begin
+        Rec.LockTable();
+        if not Rec.Get() then begin
+            Rec.Init();
+            Rec."Primary Key" := '';
+            Rec."Notifications Enabled" := true;
+            Rec.Status := Rec.Status::Idle;
+            Rec."Last Run" := CurrentDateTime();
+            Rec.Insert();
+        end;
+        exit(Rec);
+    end;
+
+    procedure ShouldRunNotifications(): Boolean
+    begin
+        exit(GetOrCreate()."Notifications Enabled");
+    end;
+
+    procedure UpdateStatus(NewStatus: Enum "Agent Run State"; ErrorMessage: Text[250])
+    var
+        AgentStatus: Record "EA Agent Status";
+    begin
+        AgentStatus := GetOrCreate();
+        AgentStatus.Status := NewStatus;
+        AgentStatus."Last Run" := CurrentDateTime();
+        AgentStatus."Last Error Message" := ErrorMessage;
+        if NewStatus = AgentStatus.Status::Error then
+            AgentStatus."Retry Count" += 1
+        else
+            AgentStatus."Retry Count" := 0;
+        AgentStatus.Modify();
+    end;
+
+    procedure IsRunning(): Boolean
+    var
+        AgentStatus: Record "EA Agent Status";
+    begin
+        AgentStatus := GetOrCreate();
+        exit(AgentStatus.Status = AgentStatus.Status::Running);
+    end;
+}
diff --git a/src/VendEntryEditHandler.Codeunit.al b/src/VendEntryEditHandler.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/VendEntryEditHandler.Codeunit.al
@@ -0,0 +1,37 @@
+codeunit 50131 "Vend. Entry Edit Handler"
+{
+    Access = Internal;
+
+    procedure UpdateRelatedAdvanceLetterEntries(EntryNo: Integer; Level: Integer)
+    var
+        VendLedgerEntry: Record "Vendor Ledger Entry";
+        RelatedEntry: Record "Vendor Ledger Entry";
+        MaxRecursionLevel: Integer;
+    begin
+        MaxRecursionLevel := 50;
+        if Level > MaxRecursionLevel then
+            Error(MaxRecursionErr, EntryNo);
+
+        VendLedgerEntry.SetLoadFields("Letter No.", "Letter Line No.", "Advance Letter Template Code", "Document No.", "Vendor No.");
+        VendLedgerEntry.ReadIsolation(IsolationLevel::UpdLock);
+        if not VendLedgerEntry.Get(EntryNo) then
+            exit;
+
+        VendLedgerEntry."Letter No." := '';
+        VendLedgerEntry."Letter Line No." := 0;
+        VendLedgerEntry."Advance Letter Template Code" := '';
+        VendLedgerEntry.Modify();
+
+        RelatedEntry.SetLoadFields("Entry No.");
+        RelatedEntry.SetRange("Closed by Entry No.", EntryNo);
+        RelatedEntry.SetRange(Open, false);
+
+        if RelatedEntry.FindSet() then
+            repeat
+                UpdateRelatedAdvanceLetterEntries(RelatedEntry."Entry No.", Level + 1);
+            until RelatedEntry.Next() = 0;
+    end;
+
+    var
+        MaxRecursionErr: Label 'Maximum recursion level exceeded for entry %1', Comment = '%1 = entry number';
+}
