diff --git a/src/BusinessSystemLogger.Codeunit.al b/src/BusinessSystemLogger.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/BusinessSystemLogger.Codeunit.al
@@ -0,0 +1,45 @@
+codeunit 50112 BusinessSystemLogger
+{
+    procedure LogVendorProcessing(VendorCode: Code[20]; ProcessingStep: Text[100])
+    var
+        ActivityLog: Record "Activity Log";
+    begin
+
+        ActivityLog.LogActivity(
+            Database::Vendor,
+            ActivityLog.Status::Success,
+            'VendorProcessing',
+            StrSubstNo('Processing completed for Vendor: %1 at step: %2', VendorCode, ProcessingStep),
+            '');
+
+        Message(VendorLoggedMsg, VendorCode);
+    end;
+
+    procedure LogSystemOperation(OperationType: Text[50]; Details: Text[250])
+    begin
+
+        Session.LogMessage('VendorProcess', StrSubstNo('Operation: %1 - Details: %2', OperationType, Details), Verbosity::Information,
+                          DataClassification::SystemMetadata, TelemetryScope::ExtensionPublisher, 'Vendor', '');
+    end;
+
+    procedure ProcessVendorBatch(var VendorBatch: Record Vendor temporary)
+    var
+        ProcessedCount: Integer;
+        VendorCode: Code[20];
+    begin
+
+        if VendorBatch.FindSet() then
+            repeat
+                VendorCode := VendorBatch."No.";
+
+                LogSystemOperation('BATCH_PROCESSING', StrSubstNo('Vendor %1 processed in batch', VendorCode));
+                ProcessedCount += 1;
+            until VendorBatch.Next() = 0;
+
+        Message(BatchCompletedMsg, ProcessedCount);
+    end;
+
