+codeunit 50003 "Clean Error Handling"
+{
+    var
+        CustomerNotFoundErr: Label 'Customer %1 was not found.', Comment = '%1 = Customer No.';
+
+    /// <summary>
+    /// Processes a customer record with proper error handling.
+    /// </summary>
+    /// <param name="CustomerNo">The customer number to process.</param>
+    procedure ProcessCustomer(CustomerNo: Code[20])
+    var
+        Customer: Record Customer;
+    begin
+        if not Customer.Get(CustomerNo) then
+            Error(CustomerNotFoundErr, CustomerNo);
+
+        Customer.TestField(Name);
+    end;
+
+    /// <summary>
+    /// Attempts to validate a single customer record.
+    /// </summary>
+    /// <param name="CustomerNo">The customer number to validate.</param>
+    [TryFunction]
+    procedure TryValidateCustomer(CustomerNo: Code[20])
+    var
+        Customer: Record Customer;
+    begin
+        Customer.Get(CustomerNo);
+        Customer.TestField(Name);
+    end;
+}
